from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(x for x in src if x.startswith(('const PAPER=','const t=','const icons=','const icon=','const btn=','const heading=','function home(')))
script=defs+"\nlet lang='ko';\n"+'''
const cases=[];for(const language of ['ko','en'])for(const width of [438,600,744,980]){lang=language;const h=document.createElement('div');h.innerHTML=home();const content=h.querySelector('.entry-hint'),id=`${language}-${width}`;content.dataset.id=id;const f=document.createElement('div');f.className='fixture welcome';f.style.width=width+'px';f.append(content);document.getElementById('fixtures').append(f);cases.push({id,width,english:language==='en'})}
function read(){return [...document.querySelectorAll('.entry-hint')].map(e=>{const r=e.parentElement.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},c=getComputedStyle(e),t=e.querySelector('span'),i=e.querySelector('svg'),tc=getComputedStyle(t),ic=getComputedStyle(i);return{id:e.dataset.id,root:box(e),icon:{box:box(i),stroke:ic.color,strokeWidth:ic.strokeWidth},text:{box:box(t),text:t.textContent,color:tc.color},style:{display:c.display,alignItems:c.alignItems,gap:c.gap,marginTop:c.marginTop,fontSize:tc.fontSize,fontWeight:tc.fontWeight,lineHeight:tc.lineHeight}}})}function getCases(){return cases}
'''
(o/'welcomeentryhint-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'welcomeentryhint-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="welcomeentryhint-original.css"><style>.fixture{position:absolute;left:30px;top:60px;padding:0}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'welcomeentryhint.html').write_text('''<!doctype html><meta charset="utf-8"><title>WelcomeEntryHint · original isolation</title><button id="welcomeentryhint-record">Record WelcomeEntryHint</button><iframe width="1400" height="650" src="welcomeentryhint-inner.html"></iframe><script>document.getElementById('welcomeentryhint-record').onclick=async()=>{const f=document.querySelector('iframe');await f.contentDocument.fonts.ready;const res=await fetch('/evidence/home-welcomeentryhint-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:f.contentWindow.read(),cases:f.contentWindow.getCases()})});if(!res.ok)throw Error('Record failed');document.getElementById('welcomeentryhint-record').textContent='WelcomeEntryHint recorded'}</script>''')
print('8 literal original entry hints')

preview=defs+"\nconst lang=new URLSearchParams(location.search).get('language')||'ko';const width=Number(new URLSearchParams(location.search).get('width')||438);const h=document.createElement('div');h.innerHTML=home();const e=h.querySelector('.entry-hint');document.querySelector('.fixture').style.width=width+'px';document.querySelector('.fixture').append(e);"
(o/'welcomeentryhint-preview.html').write_text('<!doctype html><meta charset="utf-8"><title>WelcomeEntryHint preview · original isolation</title><link rel="stylesheet" href="welcomeentryhint-original.css"><style>.fixture{position:absolute;left:30px;top:60px;padding:0}</style><div class="fixture welcome"></div><script>'+preview+'</script>')
